 78	function isPointsSame(points1: ArrayLike<number>, points2: ArrayLike<number>) {
 79	    if (points1.length !== points2.length) {
 80	        return;
 81	    }
 82	    for (let i = 0; i < points1.length; i++) {
 83	        if (points1[i] !== points2[i]) {
 84	            return;
 85	        }
 86	    }
 87	    return true;
 88	}
 89	
 90	function bboxFromPoints(points: ArrayLike<number>) {
 91	    let minX = Infinity;
 92	    let minY = Infinity;
 93	    let maxX = -Infinity;
 94	    let maxY = -Infinity;
 95	
 96	    for (let i = 0; i < points.length;) {
 97	        const x = points[i++];
 98	        const y = points[i++];
 99	        if (!isNaN(x)) {
100	            minX = Math.min(x, minX);
101	            maxX = Math.max(x, maxX);
102	        }
103	        if (!isNaN(y)) {
104	            minY = Math.min(y, minY);
105	            maxY = Math.max(y, maxY);
106	        }
107	    }
108	    return [
109	        [minX, minY],
110	        [maxX, maxY]
111	    ];
112	}
113	
114	function getBoundingDiff(points1: ArrayLike<number>, points2: ArrayLike<number>): number {
115	
116	    const [min1, max1] = bboxFromPoints(points1);
117	    const [min2, max2] = bboxFromPoints(points2);
118	
119	    // Get a max value from each corner of two boundings.
120	    return Math.max(
121	        Math.abs(min1[0] - min2[0]),
122	        Math.abs(min1[1] - min2[1]),
123	
124	        Math.abs(max1[0] - max2[0]),
125	        Math.abs(max1[1] - max2[1])
126	    );
127	}
