132	
133	function getStackedOnPoints(
134	    coordSys: Cartesian2D | Polar,
135	    data: SeriesData,
136	    dataCoordInfo: ReturnType<typeof prepareDataCoordInfo>
137	) {
138	    if (!dataCoordInfo.valueDim) {
139	        return [];
140	    }
141	
142	    const len = data.count();
143	    const points = createFloat32Array(len * 2);
144	    // Reuse one buffer for all the data items instead of allocating one for each
145	    // of them. See #20161
146	    const stackedDataBuffer: ScaleDataValue[] = [];
147	    for (let idx = 0; idx < len; idx++) {
148	        const pt = getStackedOnPoint(dataCoordInfo, coordSys, data, idx, stackedDataBuffer);
149	        points[idx * 2] = pt[0];
150	        points[idx * 2 + 1] = pt[1];
151	    }
152	
153	    return points;
154	}
155	
156	interface SteppedPoints {
157	    points: NumericArray
158	    /**
159	     * `null` if no `stackedOnPoints` is given.
160	     */
161	    stackedOnPoints: NumericArray
162	}
163	
164	/**
165	 * Generate the points of a step line.
166	 *
167	 * `stackedOnPoints` (the base line of the area of the series, see #20092) is
168	 * converted together with `points` on purpose: both arrays must stay index
169	 * aligned and share the very same progression on the base axis, otherwise
170	 * `ECPolygon` (which walks `points` forwards and `stackedOnPoints` backwards
171	 * by index) would build a skewed area.
172	 *
173	 * Null points are dropped **only** when `connectNulls` is enabled, so that the
174	 * gaps of a step line are not bridged when the user didn't ask for it. The null
175	 * state is always determined from `points`, since the base line of the area is
176	 * always defined (it falls back to the value origin) and therefore can't tell
177	 * where the gaps are.
178	 */
179	function turnPointsIntoStep(
180	    points: ArrayLike<number>,
181	    stackedOnPoints: ArrayLike<number>,
182	    coordSys: Cartesian2D | Polar,
183	    stepTurnAt: 'start' | 'end' | 'middle',
184	    connectNulls: boolean
185	): SteppedPoints {
186	    const baseAxis = coordSys.getBaseAxis();
187	    const baseIndex = baseAxis.dim === 'x' || baseAxis.dim === 'radius' ? 0 : 1;
188	    const valueIndex = 1 - baseIndex;
189	    const hasStackedOn = !!stackedOnPoints;
190	    const len = points.length;
191	
192	    // Count the points that are kept. Null points are only dropped (which bridges
193	    // the gap) when `connectNulls` is enabled.
194	    let pointCount = len / 2;
195	    if (connectNulls) {
196	        pointCount = 0;
197	        for (let i = 0; i < len; i += 2) {
198	            if (!isNaN(points[i]) && !isNaN(points[i + 1])) {
199	                pointCount++;
200	            }
201	        }
202	    }
203	
204	    // The amount of the generated points is known upfront, so they can be written
205	    // into exactly sized Float32Arrays. Compared with growing plain arrays (which
206	    // hold doubles) it roughly halves the memory that the shapes of a step line
207	    // keep alive, and it doesn't leave intermediate copies behind. See #20161
208	    const stepPointCount = pointCount > 0
209	        ? (stepTurnAt === 'middle' ? pointCount * 3 - 2 : pointCount * 2 - 1)
210	        : 0;
211	    const stepPoints = createFloat32Array(stepPointCount * 2);
212	    const stepStackedOnPoints = hasStackedOn ? createFloat32Array(stepPointCount * 2) : null;
213	
214	    /**
215	     * Write the point at `srcOffset` and the turning point(s) between it and the
216	     * point at `nextSrcOffset` (`-1` if there is no next point) into `out`.
217	     * Returns the new write offset.
218	     */
219	    function writeStepPoints(
220	        src: ArrayLike<number>,
221	        out: NumericArray,
222	        outOffset: number,
223	        srcOffset: number,
224	        nextSrcOffset: number
225	    ): number {
226	        out[outOffset] = src[srcOffset];
227	        out[outOffset + 1] = src[srcOffset + 1];
228	        outOffset += 2;
229	
230	        if (nextSrcOffset < 0) {
231	            // Last point.
232	            return outOffset;
233	        }
234	
235	        const base = src[srcOffset + baseIndex];
236	        const value = src[srcOffset + valueIndex];
237	        const nextBase = src[nextSrcOffset + baseIndex];
238	        const nextValue = src[nextSrcOffset + valueIndex];
239	
240	        switch (stepTurnAt) {
241	            case 'end':
242	                out[outOffset + baseIndex] = nextBase;
243	                out[outOffset + valueIndex] = value;
244	                outOffset += 2;
245	                break;
246	            case 'middle':
247	                const middle = (base + nextBase) / 2;
248	                out[outOffset + baseIndex] = middle;
249	                out[outOffset + valueIndex] = value;
250	                outOffset += 2;
251	                out[outOffset + baseIndex] = middle;
252	                out[outOffset + valueIndex] = nextValue;
253	                outOffset += 2;
254	                break;
255	            default:
256	                // default is start
257	                out[outOffset + baseIndex] = base;
258	                out[outOffset + valueIndex] = nextValue;
259	                outOffset += 2;
260	        }
261	        return outOffset;
262	    }
263	
264	    let outOffset = 0;
265	    let prevSrcOffset = -1;
266	    for (let i = 0; i < len; i += 2) {
267	        if (connectNulls && (isNaN(points[i]) || isNaN(points[i + 1]))) {
268	            continue;
269	        }
270	        if (prevSrcOffset >= 0) {
271	            // Both arrays are written from the same offsets on purpose, so that
272	            // they can't get out of sync. See #20092
273	            const nextOutOffset = writeStepPoints(points, stepPoints, outOffset, prevSrcOffset, i);
274	            if (hasStackedOn) {
275	                writeStepPoints(stackedOnPoints, stepStackedOnPoints, outOffset, prevSrcOffset, i);
276	            }
277	            outOffset = nextOutOffset;
278	        }
279	        prevSrcOffset = i;
280	    }
281	    // Last point
282	    if (prevSrcOffset >= 0) {
283	        writeStepPoints(points, stepPoints, outOffset, prevSrcOffset, -1);
284	        if (hasStackedOn) {
285	            writeStepPoints(stackedOnPoints, stepStackedOnPoints, outOffset, prevSrcOffset, -1);
286	        }
287	    }
288	
289	    return {
290	        points: stepPoints,
291	        stackedOnPoints: stepStackedOnPoints
292	    };
293	}
