299	function preparePolyPoints(
300	    points: NumericArray,
301	    stackedOnPoints: NumericArray,
302	    coordSys: Cartesian2D | Polar,
303	    step: LineSeriesOption['step'],
304	    connectNulls: boolean
305	): SteppedPoints {
306	    // TODO If stacked series is not step
307	    return step
308	        ? turnPointsIntoStep(points, stackedOnPoints, coordSys, step, connectNulls)
309	        : { points: points, stackedOnPoints: stackedOnPoints };
310	}
