312	/**
313	 * Clip color stops to edge. Avoid creating too large gradients.
314	 * Which may lead to blurry when GPU acceleration is enabled. See #15680
315	 *
316	 * The stops has been sorted from small to large.
317	 */
318	function clipColorStops(colorStops: ColorStop[], maxSize: number): ColorStop[] {
319	    const newColorStops: ColorStop[] = [];
320	    const len = colorStops.length;
321	    // coord will always < 0 in prevOutOfRangeColorStop.
322	    let prevOutOfRangeColorStop: ColorStop;
323	    let prevInRangeColorStop: ColorStop;
324	
325	    function lerpStop(stop0: ColorStop, stop1: ColorStop, clippedCoord: number) {
326	        const coord0 = stop0.coord;
327	        const p = (clippedCoord - coord0) / (stop1.coord - coord0);
328	        const color = lerp(p, [stop0.color, stop1.color]) as string;
329	        return { coord: clippedCoord, color } as ColorStop;
330	    }
331	
332	    for (let i = 0; i < len; i++) {
333	        const stop = colorStops[i];
334	        const coord = stop.coord;
335	        if (coord < 0) {
336	            prevOutOfRangeColorStop = stop;
337	        }
