158	/**
159	 * Generate the points of a step line.
160	 *
161	 * `stackedOnPoints` (the base line of the area of the series, see #20092) is
162	 * converted together with `points` on purpose: both arrays must stay index
163	 * aligned and share the very same progression on the base axis, otherwise
164	 * `ECPolygon` (which walks `points` forwards and `stackedOnPoints` backwards
165	 * by index) would build a skewed area.
166	 *
167	 * Null points are dropped **only** when `connectNulls` is enabled, so that the
168	 * gaps of a step line are not bridged when the user didn't ask for it. The null
169	 * state is always determined from `points`, since the base line of the area is
170	 * always defined (it falls back to the value origin) and therefore can't tell
171	 * where the gaps are.
172	 */
173	function turnPointsIntoStep(
174	    points: ArrayLike<number>,
175	    stackedOnPoints: ArrayLike<number>,
176	    coordSys: Cartesian2D | Polar,
177	    stepTurnAt: 'start' | 'end' | 'middle',
178	    connectNulls: boolean
179	): SteppedPoints {
180	    const baseAxis = coordSys.getBaseAxis();
181	    const baseIndex = baseAxis.dim === 'x' || baseAxis.dim === 'radius' ? 0 : 1;
182	    const hasStackedOn = !!stackedOnPoints;
183	
184	    if (connectNulls) {
185	        // Bridge the null gaps by simply removing the null points. The same
186	        // indices have to be removed from the base line of the area.
187	        const filteredPoints: number[] = [];
188	        const filteredStackedOnPoints: number[] = hasStackedOn ? [] : null;
189	        for (let i = 0; i < points.length; i += 2) {
190	            if (!isNaN(points[i]) && !isNaN(points[i + 1])) {
191	                filteredPoints.push(points[i], points[i + 1]);
192	                if (hasStackedOn) {
193	                    filteredStackedOnPoints.push(stackedOnPoints[i], stackedOnPoints[i + 1]);
194	                }
195	            }
196	        }
197	        points = filteredPoints;
198	        stackedOnPoints = filteredStackedOnPoints;
199	    }
200	
201	    const stepPt: number[] = [];
202	    const stepPt2: number[] = [];
203	    const pt: number[] = [];
204	    const nextPt: number[] = [];
205	
206	    function toStepPoints(rawPoints: ArrayLike<number>): number[] {
207	        const stepPoints: number[] = [];
208	        let i = 0;
209	        for (i = 0; i < rawPoints.length - 2; i += 2) {
210	            nextPt[0] = rawPoints[i + 2];
211	            nextPt[1] = rawPoints[i + 3];
212	            pt[0] = rawPoints[i];
213	            pt[1] = rawPoints[i + 1];
214	            stepPoints.push(pt[0], pt[1]);
215	
216	            switch (stepTurnAt) {
217	                case 'end':
218	                    stepPt[baseIndex] = nextPt[baseIndex];
219	                    stepPt[1 - baseIndex] = pt[1 - baseIndex];
220	                    stepPoints.push(stepPt[0], stepPt[1]);
221	                    break;
222	                case 'middle':
223	                    const middle = (pt[baseIndex] + nextPt[baseIndex]) / 2;
224	                    stepPt[baseIndex] = stepPt2[baseIndex] = middle;
225	                    stepPt[1 - baseIndex] = pt[1 - baseIndex];
226	                    stepPt2[1 - baseIndex] = nextPt[1 - baseIndex];
227	                    stepPoints.push(stepPt[0], stepPt[1]);
228	                    stepPoints.push(stepPt2[0], stepPt2[1]);
229	                    break;
230	                default:
231	                    // default is start
232	                    stepPt[baseIndex] = pt[baseIndex];
233	                    stepPt[1 - baseIndex] = nextPt[1 - baseIndex];
234	                    stepPoints.push(stepPt[0], stepPt[1]);
235	            }
236	        }
237	        // Last points
238	        if (rawPoints.length >= 2) {
239	            stepPoints.push(rawPoints[i], rawPoints[i + 1]);
240	        }
241	        return stepPoints;
242	    }
243	
244	    return {
245	        points: toStepPoints(points),
246	        stackedOnPoints: hasStackedOn ? toStepPoints(stackedOnPoints) : null
247	    };
248	}
