1177	    _initSymbolLabelAnimation(
1178	        data: SeriesData,
1179	        coordSys: Polar | Cartesian2D,
1180	        clipShape: PolarArea | Cartesian2DArea
1181	    ) {
1182	        let isHorizontalOrRadial: boolean;
1183	        let isCoordSysPolar: boolean;
1184	        const baseAxis = coordSys.getBaseAxis();
1185	        const isAxisInverse = baseAxis.inverse;
1186	        if (coordSys.type === 'cartesian2d') {
1187	            isHorizontalOrRadial = (baseAxis as Axis2D).isHorizontal();
1188	            isCoordSysPolar = false;
1189	        }
1190	        else if (coordSys.type === 'polar') {
1191	            isHorizontalOrRadial = baseAxis.dim === 'angle';
1192	            isCoordSysPolar = true;
1193	        }
1194	
1195	        const seriesModel = data.hostModel;
1196	        let seriesDuration = seriesModel.get('animationDuration');
1197	        if (zrUtil.isFunction(seriesDuration)) {
1198	            seriesDuration = seriesDuration(null);
1199	        }
1200	        const seriesDelay = seriesModel.get('animationDelay') || 0;
1201	        const seriesDelayValue = zrUtil.isFunction(seriesDelay)
1202	            ? seriesDelay(null)
1203	            : seriesDelay;
1204	
1205	        data.eachItemGraphicEl(function (symbol: SymbolExtended, idx) {
1206	            const el = symbol;
1207	            if (el) {
1208	                const point = [symbol.x, symbol.y];
1209	                let start;
1210	                let end;
1211	                let current;
1212	                if (clipShape) {
1213	                    if (isCoordSysPolar) {
1214	                        const polarClip = clipShape as PolarArea;
1215	                        const coord = (coordSys as Polar).pointToCoord(point);
1216	                        if (isHorizontalOrRadial) {
1217	                            start = polarClip.startAngle;
1218	                            end = polarClip.endAngle;
1219	                            current = -coord[1] / 180 * Math.PI;
1220	                        }
1221	                        else {
1222	                            start = polarClip.r0;
1223	                            end = polarClip.r;
1224	                            current = coord[0];
1225	                        }
1226	                    }
1227	                    else {
1228	                        const gridClip = clipShape as Cartesian2DArea;
1229	                        if (isHorizontalOrRadial) {
1230	                            start = gridClip.x;
1231	                            end = gridClip.x + gridClip.width;
1232	                            current = symbol.x;
1233	                        }
1234	                        else {
1235	                            start = gridClip.y + gridClip.height;
1236	                            end = gridClip.y;
1237	                            current = symbol.y;
1238	                        }
1239	                    }
1240	                }
1241	                let ratio = end === start ? 0 : (current - start) / (end - start);
1242	                if (isAxisInverse) {
1243	                    ratio = 1 - ratio;
1244	                }
1245	
1246	                const delay = zrUtil.isFunction(seriesDelay) ? seriesDelay(idx)
1247	                    : (seriesDuration * ratio) + seriesDelayValue;
1248	
1249	                const symbolPath = el.getSymbolPath();
1250	                const text = symbolPath.getTextContent();
1251	
1252	                el.attr({ scaleX: 0, scaleY: 0 });
1253	                el.animateTo({
1254	                    scaleX: 1,
1255	                    scaleY: 1
1256	                }, {
1257	                    duration: 200,
1258	                    setToFinal: true,
1259	                    delay: delay
1260	                });
1261	
1262	                if (text) {
1263	                    text.animateFrom({
1264	                        style: {
1265	                            opacity: 0
1266	                        }
1267	                    }, {
1268	                        duration: 300,
1269	                        delay: delay
1270	                    });
1271	                }
1272	
1273	                (symbolPath as ECElement).disableLabelAnimation = true;
1274	            }
1275	        });
1276	    }
