1344	
1345	        if (endLabel) {
1346	            // NOTE: Don't remove percent < 1. percent === 1 means the first frame during render.
1347	            // The label is not prepared at this time.
1348	            if (percent < 1 && animationRecord.originalX == null) {
1349	                animationRecord.originalX = endLabel.x;
1350	                animationRecord.originalY = endLabel.y;
1351	            }
