1361	            const isHorizontal = baseAxis.isHorizontal();
1362	            const isBaseInversed = baseAxis.inverse;
1363	            const clipShape = clipRect.shape;
1364	
1365	            const xOrY = isBaseInversed
1366	                ? isHorizontal ? clipShape.x : (clipShape.y + clipShape.height)
1367	                : isHorizontal ? (clipShape.x + clipShape.width) : clipShape.y;
1368	            const distanceX = (isHorizontal ? distance : 0) * (isBaseInversed ? -1 : 1);
1369	            const distanceY = (isHorizontal ? 0 : -distance) * (isBaseInversed ? -1 : 1);
1370	            const dim = isHorizontal ? 'x' : 'y';
1371	
1372	            const dataIndexRange = getIndexRange(points, xOrY, dim);
1373	            const indices = dataIndexRange.range;
1374	
1375	            const diff = indices[1] - indices[0];
1376	            let value: ParsedValue;
1377	            if (diff >= 1) {
1378	                // diff > 1 && connectNulls, which is on the null data.
1379	                if (diff > 1 && !connectNulls) {
1380	                    const pt = getPointAtIndex(points, indices[0]);
1381	                    endLabel.attr({
1382	                        x: pt[0] + distanceX,
1383	                        y: pt[1] + distanceY
1384	                    });
1385	                    valueAnimation && (value = seriesModel.getRawValue(indices[0]) as ParsedValue);
1386	                }
1387	                else {
1388	                    const pt = polyline.getPointOn(xOrY, dim);
1389	                    pt && endLabel.attr({
1390	                        x: pt[0] + distanceX,
1391	                        y: pt[1] + distanceY
1392	                    });
1393	
1394	                    const startValue = seriesModel.getRawValue(indices[0]) as ParsedValue;
1395	                    const endValue = seriesModel.getRawValue(indices[1]) as ParsedValue;
