1439	        const diff = lineAnimationDiff(
1440	            this._data, data,
1441	            this._stackedOnPoints, stackedOnPoints,
1442	            this._coordSys, coordSys,
1443	            this._valueOrigin, valueOrigin
1444	        );
1445	
1446	        let current = diff.current;
1447	        let stackedOnCurrent = diff.stackedOnCurrent;
1448	        let next = diff.next;
1449	        let stackedOnNext = diff.stackedOnNext;
1450	        if (step) {
1451	            // TODO If stacked series is not step
1452	            // NOTE: `points` and `stackedOnPoints` must be turned into step points
