1455	                diff.current, diff.stackedOnCurrent, coordSys, step, connectNulls
1456	            );
1457	            const steppedNext = turnPointsIntoStep(
1458	                diff.next, diff.stackedOnNext, coordSys, step, connectNulls
1459	            );
1460	            current = steppedCurrent.points;
1461	            stackedOnCurrent = steppedCurrent.stackedOnPoints;
1462	            next = steppedNext.points;
1463	            stackedOnNext = steppedNext.stackedOnPoints;
1464	        }
1465	        // Don't apply animation if diff is large.
1466	        // For better result and avoid memory explosion problems like
1467	        // https://github.com/apache/incubator-echarts/issues/12229
