1469	            || (polygon && getBoundingDiff(stackedOnCurrent, stackedOnNext) > 3000)
1470	        ) {
1471	            polyline.stopAnimation();
1472	            polyline.setShape({
1473	                points: next
1474	            });
1475	            if (polygon) {
1476	                polygon.stopAnimation();
1477	                polygon.setShape({
1478	                    points: next,
1479	                    stackedOnPoints: stackedOnNext
1480	                });
