1485	        (polyline.shape as any).__points = diff.current;
1486	        polyline.shape.points = current;
1487	
1488	        const target = {
1489	            shape: {
1490	                points: next
1491	            }
1492	        };
1493	        // Also animate the original points.
1494	        // If points reference is changed when turning into step line.
1495	        if (diff.current !== current) {
1496	            (target.shape as any).__points = diff.next;
1497	        }
1498	
1499	        // Stop previous animation.
1500	        polyline.stopAnimation();
1501	        graphic.updateProps(polyline, target, seriesModel);
1502	
1503	        if (polygon) {
1504	            polygon.setShape({
