1521	        const updatedDataInfo: {
1522	            el: SymbolExtended,
1523	            ptIdx: number
1524	        }[] = [];
1525	        const diffStatus = diff.status;
1526	
1527	        for (let i = 0; i < diffStatus.length; i++) {
1528	            const cmd = diffStatus[i].cmd;
1529	            if (cmd === '=') {
1530	                const el = data.getItemGraphicEl(diffStatus[i].idx1) as SymbolExtended;
1531	                if (el) {
