    20	import {prepareDataCoordInfo, getStackedOnPoint} from './helper';
    21	import SeriesData from '../../data/SeriesData';
    22	import type Cartesian2D from '../../coord/cartesian/Cartesian2D';
    23	import type Polar from '../../coord/polar/Polar';
    24	import { LineSeriesOption } from './LineSeries';
    25	import { createFloat32Array } from '../../util/vendor';
    26	
    27	interface DiffItem {
    28	    cmd: '+' | '=' | '-'
    29	    idx: number
    30	    idx1?: number
    31	}
    32	
    33	function diffData(oldData: SeriesData, newData: SeriesData) {
    34	    const diffResult: DiffItem[] = [];
    35	
    36	    newData.diff(oldData)
    37	        .add(function (idx) {
    38	            diffResult.push({cmd: '+', idx: idx});
    39	        })
    40	        .update(function (newIdx, oldIdx) {
    41	            diffResult.push({cmd: '=', idx: oldIdx, idx1: newIdx});
    42	        })
    43	        .remove(function (idx) {
    44	            diffResult.push({cmd: '-', idx: idx});
    45	        })
    46	        .execute();
    47	
    48	    return diffResult;
    49	}
    50	
    51	export default function lineAnimationDiff(
    52	    oldData: SeriesData, newData: SeriesData,
    53	    oldStackedOnPoints: ArrayLike<number>, newStackedOnPoints: ArrayLike<number>,
    54	    oldCoordSys: Cartesian2D | Polar, newCoordSys: Cartesian2D | Polar,
    55	    oldValueOrigin: LineSeriesOption['areaStyle']['origin'],
    56	    newValueOrigin: LineSeriesOption['areaStyle']['origin']
    57	) {
    58	    const diff = diffData(oldData, newData);
    59	
    60	    // let newIdList = newData.mapArray(newData.getId);
    61	    // let oldIdList = oldData.mapArray(oldData.getId);
    62	
    63	    // convertToIntId(newIdList, oldIdList);
    64	
    65	    // // FIXME One data ?
    66	    // diff = arrayDiff(oldIdList, newIdList);
    67	
    68	    const currPoints: number[] = [];
    69	    const nextPoints: number[] = [];
    70	    // Points for stacking base line
    71	    const currStackedPoints: number[] = [];
    72	    const nextStackedPoints: number[] = [];
    73	
    74	    const status = [];
    75	    const sortedIndices: number[] = [];
    76	    const rawIndices: number[] = [];
    77	
    78	    const newDataOldCoordInfo = prepareDataCoordInfo(oldCoordSys, newData, oldValueOrigin);
    79	    // const oldDataNewCoordInfo = prepareDataCoordInfo(newCoordSys, oldData, newValueOrigin);
    80	
    81	    const oldPoints = oldData.getLayout('points') as number[] || [];
    82	    const newPoints = newData.getLayout('points') as number[] || [];
    83	
    84	    for (let i = 0; i < diff.length; i++) {
    85	        const diffItem = diff[i];
    86	        let pointAdded = true;
    87	
    88	        let oldIdx2: number;
    89	        let newIdx2: number;
    90	
    91	        // FIXME, animation is not so perfect when dataZoom window moves fast
    92	        // Which is in case remvoing or add more than one data in the tail or head
    93	        switch (diffItem.cmd) {
    94	            case '=':
    95	                oldIdx2 = diffItem.idx * 2;
    96	                newIdx2 = diffItem.idx1 * 2;
    97	                let currentX = oldPoints[oldIdx2];
    98	                let currentY = oldPoints[oldIdx2 + 1];
    99	                const nextX = newPoints[newIdx2];
   100	                const nextY = newPoints[newIdx2 + 1];
   101	
   102	                // If previous data is NaN, use next point directly
   103	                if (isNaN(currentX) || isNaN(currentY)) {
   104	                    currentX = nextX;
   105	                    currentY = nextY;
   106	                }
   107	                currPoints.push(currentX, currentY);
   108	                nextPoints.push(nextX, nextY);
   109	
   110	                currStackedPoints.push(oldStackedOnPoints[oldIdx2], oldStackedOnPoints[oldIdx2 + 1]);
   111	                nextStackedPoints.push(newStackedOnPoints[newIdx2], newStackedOnPoints[newIdx2 + 1]);
   112	
   113	                rawIndices.push(newData.getRawIndex(diffItem.idx1));
   114	                break;
   115	            case '+':
   116	                const newIdx = diffItem.idx;
   117	                const newDataDimsForPoint = newDataOldCoordInfo.dataDimsForPoint;
   118	                const oldPt = oldCoordSys.dataToPoint([
   119	                    newData.get(newDataDimsForPoint[0], newIdx),
   120	                    newData.get(newDataDimsForPoint[1], newIdx)
   121	                ]);
   122	                newIdx2 = newIdx * 2;
   123	                currPoints.push(oldPt[0], oldPt[1]);
   124	
   125	                nextPoints.push(newPoints[newIdx2], newPoints[newIdx2 + 1]);
   126	
   127	                const stackedOnPoint = getStackedOnPoint(newDataOldCoordInfo, oldCoordSys, newData, newIdx);
   128	
   129	                currStackedPoints.push(stackedOnPoint[0], stackedOnPoint[1]);
   130	                nextStackedPoints.push(newStackedOnPoints[newIdx2], newStackedOnPoints[newIdx2 + 1]);
   131	
   132	                rawIndices.push(newData.getRawIndex(newIdx));
   133	                break;
   134	            case '-':
   135	                pointAdded = false;
   136	        }
   137	
   138	        // Original indices
   139	        if (pointAdded) {
   140	            status.push(diffItem);
   141	            sortedIndices.push(sortedIndices.length);
   142	        }
   143	    }
   144	
   145	    // Diff result may be crossed if all items are changed
   146	    // Sort by data index
   147	    sortedIndices.sort(function (a, b) {
   148	        return rawIndices[a] - rawIndices[b];
   149	    });
   150	
   151	    const len = currPoints.length;
   152	    const sortedCurrPoints = createFloat32Array(len);
   153	    const sortedNextPoints = createFloat32Array(len);
   154	
   155	    const sortedCurrStackedPoints = createFloat32Array(len);
   156	    const sortedNextStackedPoints = createFloat32Array(len);
   157	
   158	    const sortedStatus = [];
   159	    for (let i = 0; i < sortedIndices.length; i++) {
   160	        const idx = sortedIndices[i];
   161	        const i2 = i * 2;
   162	        const idx2 = idx * 2;
   163	        sortedCurrPoints[i2] = currPoints[idx2];
   164	        sortedCurrPoints[i2 + 1] = currPoints[idx2 + 1];
   165	        sortedNextPoints[i2] = nextPoints[idx2];
   166	        sortedNextPoints[i2 + 1] = nextPoints[idx2 + 1];
   167	
   168	        sortedCurrStackedPoints[i2] = currStackedPoints[idx2];
   169	        sortedCurrStackedPoints[i2 + 1] = currStackedPoints[idx2 + 1];
   170	        sortedNextStackedPoints[i2] = nextStackedPoints[idx2];
   171	        sortedNextStackedPoints[i2 + 1] = nextStackedPoints[idx2 + 1];
   172	
   173	        sortedStatus[i] = status[idx];
   174	    }
   175	
   176	    return {
   177	        current: sortedCurrPoints,
   178	        next: sortedNextPoints,
   179	
   180	        stackedOnCurrent: sortedCurrStackedPoints,
   181	        stackedOnNext: sortedNextStackedPoints,
   182	
   183	        status: sortedStatus
   184	    };
   185	}
