/* scratch: equivalence check between original turnPointsIntoStep and new impl */
import { EChartsType } from '@/src/echarts';
import { createChart, getECModel, getGraphicElements, removeChart } from '../../../core/utHelper';

function getPolyPoints(chart: EChartsType, type: 'ec-polyline' | 'ec-polygon'): ArrayLike<number> {
    const els = getGraphicElements(chart, 'series', 0);
    for (let i = 0; i < els.length; i++) {
        if (els[i].type === type) {
            return (els[i] as any).shape.points;
        }
    }
    return null;
}

// ---- verbatim copy of the HEAD implementation ----
function originalTurnPointsIntoStep(
    points: ArrayLike<number>,
    stackedOnPoints: ArrayLike<number>,
    baseIndex: number,
    stepTurnAt: 'start' | 'end' | 'middle',
    connectNulls: boolean
) {
    const hasStackedOn = !!stackedOnPoints;
    if (connectNulls) {
        const filteredPoints: number[] = [];
        const filteredStackedOnPoints: number[] = hasStackedOn ? [] : null;
        for (let i = 0; i < points.length; i += 2) {
            if (!isNaN(points[i]) && !isNaN(points[i + 1])) {
                filteredPoints.push(points[i], points[i + 1]);
                if (hasStackedOn) {
                    filteredStackedOnPoints.push(stackedOnPoints[i], stackedOnPoints[i + 1]);
                }
            }
        }
        points = filteredPoints;
        stackedOnPoints = filteredStackedOnPoints;
    }
    const stepPt: number[] = [];
    const stepPt2: number[] = [];
    const pt: number[] = [];
    const nextPt: number[] = [];
    function toStepPoints(rawPoints: ArrayLike<number>): number[] {
        const stepPoints: number[] = [];
        let i = 0;
        for (i = 0; i < rawPoints.length - 2; i += 2) {
            nextPt[0] = rawPoints[i + 2];
            nextPt[1] = rawPoints[i + 3];
            pt[0] = rawPoints[i];
            pt[1] = rawPoints[i + 1];
            stepPoints.push(pt[0], pt[1]);
            switch (stepTurnAt) {
                case 'end':
                    stepPt[baseIndex] = nextPt[baseIndex];
                    stepPt[1 - baseIndex] = pt[1 - baseIndex];
                    stepPoints.push(stepPt[0], stepPt[1]);
                    break;
                case 'middle':
                    const middle = (pt[baseIndex] + nextPt[baseIndex]) / 2;
                    stepPt[baseIndex] = stepPt2[baseIndex] = middle;
                    stepPt[1 - baseIndex] = pt[1 - baseIndex];
                    stepPt2[1 - baseIndex] = nextPt[1 - baseIndex];
                    stepPoints.push(stepPt[0], stepPt[1]);
                    stepPoints.push(stepPt2[0], stepPt2[1]);
                    break;
                default:
                    stepPt[baseIndex] = pt[baseIndex];
                    stepPt[1 - baseIndex] = nextPt[1 - baseIndex];
                    stepPoints.push(stepPt[0], stepPt[1]);
            }
        }
        if (rawPoints.length >= 2) {
            stepPoints.push(rawPoints[i], rawPoints[i + 1]);
        }
        return stepPoints;
    }
    return {
        points: toStepPoints(points),
        stackedOnPoints: hasStackedOn ? toStepPoints(stackedOnPoints) : null
    };
}

const DATASETS: (number | null)[][] = [
    [],
    [10],
    [10, 20],
    [10, 20, 30],
    [10, 20, 30, 40, 50],
    [10, null, 30, null, 50],
    [null, 20, 30, 40, null],
    [null, null, null, null, null]
];

describe('scratch/step-equivalence', function () {
    let chart: EChartsType;
    beforeEach(function () {
        chart = createChart();
    });
    afterEach(function () {
        removeChart(chart);
    });

    (['start', 'middle', 'end'] as const).forEach(function (step) {
        [false, true].forEach(function (connectNulls) {
            [false, true].forEach(function (verticalBase) {
                DATASETS.forEach(function (data, di) {
                    const name = `step=${step} connectNulls=${connectNulls} verticalBase=${verticalBase} data#${di}`;
                    it(name, function () {
                        const cat = ['a', 'b', 'c', 'd', 'e'];
                        chart.setOption({
                            animation: false,
                            xAxis: verticalBase ? {} : { type: 'category', data: cat },
                            yAxis: verticalBase ? { type: 'category', data: cat } : {},
                            series: [{
                                type: 'line',
                                step,
                                connectNulls,
                                areaStyle: {},
                                data: verticalBase
                                    ? data.map((v, i) => (v == null ? [null, i] : [v, i]))
                                    : data
                            }]
                        });
                        const layout = getECModel(chart).getSeriesByIndex(0)
                            .getData().getLayout('points') as ArrayLike<number> || [];
                        const expected = originalTurnPointsIntoStep(
                            layout, null, verticalBase ? 1 : 0, step, connectNulls
                        ).points;
                        const actual = getPolyPoints(chart, 'ec-polyline');
                        expect(actual.length).toEqual(expected.length);
                        for (let i = 0; i < expected.length; i++) {
                            if (isNaN(expected[i])) {
                                expect(isNaN(actual[i])).toBe(true);
                            }
                            else {
                                expect(Math.abs(actual[i] - expected[i])).toBeLessThan(1e-3);
                            }
                        }
                    });
                });
            });
        });
    });
});

