    width?: number,
    height?: number,
    theme?: Parameters<typeof init>[1],
    opts?: Parameters<typeof init>[2]
}): EChartsType {
    params = params || {};
    const el = document.createElement('div');
    el.style.cssText = [
        'visibility:hidden',
        'width:' + (params.width || '500') + 'px',
        'height:' + (params.height || '400') + 'px',
        'position:absolute',
        'bottom:0',
        'right:0'
    ].join(';');
