/* scratch: animated step path checks */
import { EChartsType } from '@/src/echarts';
import { createChart, getGraphicElements, removeChart } from '../../../core/utHelper';
import { ECPolyline } from '@/src/chart/line/poly';

function getEl(chart: EChartsType, type: 'ec-polyline' | 'ec-polygon'): any {
    const els = getGraphicElements(chart, 'series', 0);
    for (let i = 0; i < els.length; i++) {
        if (els[i].type === type) {
            return els[i];
        }
    }
    return null;
}

function forwardAnimations(el: any) {
    const animators = (el.animators || []).slice();
    for (let i = 0; i < animators.length; i++) {
        const clip = animators[i]._clip;
        clip && clip.onframe(1);
    }
}

function makeOpt(data: any[], cats: string[], connectNulls: boolean, animation: boolean) {
    return {
        animation,
        animationDurationUpdate: 500,
        xAxis: { type: 'category' as const, data: cats },
        yAxis: {},
        series: [{
            type: 'line' as const,
            step: 'start' as const,
            connectNulls,
            areaStyle: {},
            data
        }]
    };
}

describe('scratch/animated-step', function () {
    let chart: EChartsType;
    let ref: EChartsType;
    beforeEach(function () {
        chart = createChart();
        ref = createChart();
    });
    afterEach(function () {
        removeChart(chart);
        removeChart(ref);
    });

    const cases: {name: string, connectNulls: boolean, from: any, to: any, cats1: string[], cats2: string[]}[] = [
        {
            name: 'same length, values change',
            connectNulls: false,
            cats1: ['a', 'b', 'c'], cats2: ['a', 'b', 'c'],
            from: [1, 2, 3], to: [3, 2, 1]
        },
        {
            name: 'more data',
            connectNulls: false,
            cats1: ['a', 'b', 'c'], cats2: ['a', 'b', 'c', 'd', 'e'],
            from: [1, 2, 3], to: [3, 2, 1, 5, 6]
        },
        {
            name: 'less data',
            connectNulls: false,
            cats1: ['a', 'b', 'c', 'd', 'e'], cats2: ['a', 'b', 'c'],
            from: [1, 2, 3, 4, 5], to: [3, 2, 1]
        },
        {
            name: 'connectNulls, null appears',
            connectNulls: true,
            cats1: ['a', 'b', 'c', 'd'], cats2: ['a', 'b', 'c', 'd'],
            from: [1, 2, 3, 4], to: [1, null, 3, 4]
        },
        {
            name: 'connectNulls, null disappears',
            connectNulls: true,
            cats1: ['a', 'b', 'c', 'd'], cats2: ['a', 'b', 'c', 'd'],
            from: [1, null, 3, 4], to: [1, 2, 3, 4]
        },
        {
            name: 'connectNulls, more data with nulls',
            connectNulls: true,
            cats1: ['a', 'b', 'c'], cats2: ['a', 'b', 'c', 'd', 'e'],
            from: [1, null, 3], to: [1, 2, 3, null, 5]
        }
    ];

    cases.forEach(function (c) {
        it(c.name, function () {
            chart.setOption(makeOpt(c.from, c.cats1, c.connectNulls, true));
            chart.setOption(makeOpt(c.to, c.cats2, c.connectNulls, true));
            const polyline = getEl(chart, 'ec-polyline');
            const polygon = getEl(chart, 'ec-polygon');
            forwardAnimations(polyline);
            forwardAnimations(polygon);

            ref.setOption(makeOpt(c.to, c.cats2, c.connectNulls, false));
            const refPolyline = getEl(ref, 'ec-polyline');
            const refPolygon = getEl(ref, 'ec-polygon');

            const actual = Array.prototype.slice.call(polyline.shape.points);
            const expected = Array.prototype.slice.call(refPolyline.shape.points);
            // eslint-disable-next-line no-console
            console.log(c.name, 'points len', actual.length, 'expected len', expected.length);
            // eslint-disable-next-line no-console
            console.log('  actual  ', JSON.stringify(actual.map((v: number) => Math.round(v * 10) / 10)));
            // eslint-disable-next-line no-console
            console.log('  expected', JSON.stringify(expected.map((v: number) => Math.round(v * 10) / 10)));
            // eslint-disable-next-line no-console
            console.log('  polygon stackedOn len', polygon.shape.stackedOnPoints.length,
                'points len', polygon.shape.points.length,
                'ref', refPolygon.shape.stackedOnPoints.length);
        });
    });

    it('mechanism: typed array target cannot grow during animation', function () {
        function run(makeArr: (a: number[]) => ArrayLike<number>) {
            const el = new ECPolyline({
                shape: { points: makeArr([0, 0, 1, 1, NaN, NaN]) }
            });
            el.animateTo({
                shape: { points: makeArr([0, 0, 1, 1, 2, 2, 3, 3, 4, 4]) as any }
            }, { duration: 500 });
            forwardAnimations(el);
            return Array.prototype.slice.call(el.shape.points);
        }
        const plain = run(a => a.slice());
        const typed = run(a => new Float32Array(a));
        // eslint-disable-next-line no-console
        console.log('plain result', JSON.stringify(plain));
        // eslint-disable-next-line no-console
        console.log('typed result', JSON.stringify(typed));
    });
});

